        |r| Ok((
            r.get::<_, i64>(0)?,
            r.get::<_, String>(1)?,
            r.get::<_, String>(2)?,
            r.get::<_, String>(3)?,
            r.get::<_, i64>(4)?,
        )),
    );
    match row {
        Ok((id, owner, title, body, escalation_ref)) => {
            let mut report = json!({
                "id": id,
                "owner": owner,
                "title": title,
                "body": report_body(body),
            });
            if escalation_ref > 0 {
                report["escalation_ref"] = json!(escalation_ref);
            }
            HttpResponse::Ok().json(json!({ "report": report }))
        }
        Err(_) => HttpResponse::NotFound().json(json!({ "error": "not found" })),
    }
}

